#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <SPI.h>

#define TFT_CS 10
#define TFT_DC 9
#define TFT_RST 8

Adafruit_ST7735 pantalla = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

// DIMENSIONES DE LA PANTALLA ST7735
const int ANCHO_PANTALLA = 128;
const int ALTO_PANTALLA = 160;

// VARIABLES DE LA SERPIENTE ARTICULADA
const int MAX_LARGO = 60;      // Largo máximo de segmentos
int cuerpoX[MAX_LARGO];        // Posiciones X de cada parte del cuerpo
int cuerpoY[MAX_LARGO];        // Posiciones Y de cada parte del cuerpo
int largoActual = 3;           // Cantidad de segmentos (empieza con 3)
int velocidad = 5;             // Distancia entre segmentos (5px evita huecos)

// VARIABLES DE LAS MANZANAS
const int cantidadmanzanas = 3;
int manzanaX[cantidadmanzanas];
int manzanaY[cantidadmanzanas];

// PINES DEL JOYSTICK
const int PIN_JOYSTICK_X = A0; 
const int PIN_JOYSTICK_Y = A1; 

int nivel = 1;
bool juegoIniciado = false; 
int puntuacion = 0;

// DIRECCIONES DE LA SERPIENTE
enum Direccion { ARRIBA, ABAJO, IZQUIERDA, DERECHA };
Direccion dirActual = ARRIBA;

void setup() {
  pantalla.initR(INITR_BLACKTAB);
  pantalla.fillScreen(ST77XX_WHITE);
  randomSeed(analogRead(A2));
  mostrarMenuInicial();
}

void loop() {
  int valorX = analogRead(PIN_JOYSTICK_X);
  int valorY = analogRead(PIN_JOYSTICK_Y);

  if (!juegoIniciado) {
    // === MODO SELECCIÓN DE NIVEL ===
    if (valorY < 200) {
      juegoIniciado = true;
      dirActual = ARRIBA; 
      largoActual = 3;
      puntuacion = 0;     
      comenzarJuego();    
    }

    if (valorX < 200 && nivel > 1) {
      nivel--; 
      actualizarMenu();
      delay(300); 
    }
    else if (valorX > 850 && nivel < 3) {
      nivel++; 
      actualizarMenu();
      delay(300); 
    }
    delay(30); 
  } 
  else {
    // === MODO JUEGO EN MARCHA ===

    // Mostrar puntuación en pantalla
    pantalla.setCursor(5, 5);
    pantalla.setTextColor(ST77XX_BLACK, ST77XX_WHITE);
    pantalla.setTextSize(1);
    pantalla.print("Score: ");
    pantalla.print(puntuacion);
    puntuacion++; 

    // 1. DETECTAMOS EL CAMBIO DE DIRECCIÓN
    if (valorX < 200 && dirActual != DERECHA) {
      dirActual = IZQUIERDA;
    } else if (valorX > 800 && dirActual != IZQUIERDA) {
      dirActual = DERECHA;
    } else if (valorY < 200 && dirActual != ABAJO) {
      dirActual = ARRIBA;
    } else if (valorY > 800 && dirActual != ARRIBA) {
      dirActual = ABAJO;
    }

    // 2. BORRAMOS SOLO LA PUNTA DE LA COLA Y LA LENGUA ANTERIOR
    borrarCola();

    // 3. DESPLAZAMOS EL CUERPO Y MOVEMOS LA CABEZA
    moverSerpiente();

    // 4. REVISAR SI CHOCÓ BORDES, OBSTÁCULOS O CONSIGO MISMA
    if (verificarMuerte()) {
      pantalla.fillScreen(ST77XX_WHITE);
      pantalla.setCursor(20, 50);
      pantalla.setTextColor(ST77XX_BLACK, ST77XX_WHITE);
      pantalla.setTextSize(2);
      pantalla.println("MORISTE");
      pantalla.setCursor(25, 70);
      pantalla.println("Puntos:");
      pantalla.setCursor(60, 100);
      pantalla.println(puntuacion);
      delay(3000);
      pantalla.fillScreen(ST77XX_WHITE);
      juegoIniciado = false;
      mostrarMenuInicial();
      return; 
    }

    // 5. DIBUJAR SERPIENTE Y VERIFICAR MANZANAS
    dibujarSerpiente(); 
    comerManzana();
    dibujarManzanas();

    // 6. CONTROL DE VELOCIDAD CONSTANTE
    delay(150);
  }
}

// --- MOVIMIENTO ARTICULADO ---
void moverSerpiente() {
  // Cada segmento toma la posición del segmento anterior (de atrás hacia adelante)
  for (int i = largoActual - 1; i > 0; i--) {
    cuerpoX[i] = cuerpoX[i - 1];
    cuerpoY[i] = cuerpoY[i - 1];
  }

  // La cabeza (índice 0) avanza en la dirección actual
  switch (dirActual) {
    case ARRIBA:    cuerpoY[0] -= velocidad; break;
    case ABAJO:     cuerpoY[0] += velocidad; break;
    case IZQUIERDA: cuerpoX[0] -= velocidad; break;
    case DERECHA:   cuerpoX[0] += velocidad; break;
  }
}

// --- DIBUJO Y LIMPIEZA ---
void borrarCola() {
  // 1. Borra el último segmento de la cola
  int colaX = cuerpoX[largoActual - 1];
  int colaY = cuerpoY[largoActual - 1];
  pantalla.fillCircle(colaX, colaY, 3, ST77XX_WHITE);

  // 2. Borra la lengua anterior de la cabeza (pintando de blanco en las 4 posibles direcciones)
  int cabX = cuerpoX[0];
  int cabY = cuerpoY[0];
  pantalla.drawLine(cabX, cabY - 4, cabX, cabY - 5, ST77XX_WHITE); // Arriba
  pantalla.drawLine(cabX, cabY + 4, cabX, cabY + 5, ST77XX_WHITE); // Abajo
  pantalla.drawLine(cabX - 4, cabY, cabX - 5, cabY, ST77XX_WHITE); // Izquierda
  pantalla.drawLine(cabX + 4, cabY, cabX + 5, cabY, ST77XX_WHITE); // Derecha
}

void dibujarSerpiente() {
  // 1. Dibuja todo el cuerpo (desde el segmento 1 hasta el final)
  for (int i = 1; i < largoActual; i++) {
    pantalla.fillCircle(cuerpoX[i], cuerpoY[i], 3, ST77XX_GREEN);
  }

  // 2. Dibuja la cabeza encima (índice 0) para borrar los ojos anteriores
  int x = cuerpoX[0];
  int y = cuerpoY[0];
  pantalla.fillCircle(x, y, 3, ST77XX_GREEN);

  // 3. Dibuja ojos y lengua roja según la dirección
  switch (dirActual) {
    case ARRIBA:
      pantalla.drawPixel(x - 2, y - 1, ST77XX_BLACK);
      pantalla.drawPixel(x + 2, y - 1, ST77XX_BLACK);
      pantalla.drawLine(x, y - 3, x, y - 5, ST77XX_RED);
      break;
    case ABAJO:
      pantalla.drawPixel(x - 2, y + 1, ST77XX_BLACK);
      pantalla.drawPixel(x + 2, y + 1, ST77XX_BLACK);
      pantalla.drawLine(x, y + 3, x, y + 5, ST77XX_RED);
      break;
    case IZQUIERDA:
      pantalla.drawPixel(x - 1, y - 2, ST77XX_BLACK);
      pantalla.drawPixel(x - 1, y + 2, ST77XX_BLACK);
      pantalla.drawLine(x - 3, y, x - 5, y, ST77XX_RED);
      break;
    case DERECHA:
      pantalla.drawPixel(x + 1, y - 2, ST77XX_BLACK);
      pantalla.drawPixel(x + 1, y + 2, ST77XX_BLACK);
      pantalla.drawLine(x + 3, y, x + 5, y, ST77XX_RED);
      break;
  }
}

// --- FUNCIÓN DE VERIFICACIÓN DE MUERTE ---
bool verificarMuerte() {
  int x = cuerpoX[0];
  int y = cuerpoY[0];

  // 1. Verificar colisión con los bordes físicos de la pantalla
  if (x < 3 || x > (ANCHO_PANTALLA - 3) || y < 3 || y > (ALTO_PANTALLA - 3)) {
    return true; 
  }

  // 2. Verificar colisión con los obstáculos según el nivel actual
  if (nivel == 2) {
    if (x >= 0 && x <= 32 && y >= 0 && y <= 32) return true;
    if (x >= 105 && x <= 130 && y >= 0 && y <= 27) return true;
    if (x >= 51 && x <= 81 && y >= 122 && y <= 162) return true;
  }
  else if (nivel == 3) {
    if (x >= 38 && x <= 90 && y >= 0 && y <= 15) return true;
    if (x >= 34 && x <= 94 && y >= 130 && y <= 160) return true;
    if (x >= 0 && x <= 23 && y >= 60 && y <= 100) return true;
  }

  // 3. Verificar colisión consigo misma (empieza desde i = 3 para no chocar con el cuello al doblar)
  for (int i = 3; i < largoActual; i++) {
    if (abs(x - cuerpoX[i]) < 4 && abs(y - cuerpoY[i]) < 4) {
      return true;
    }
  }

  return false;
}

// --- FUNCIONES MENÚ ---
void mostrarMenuInicial() {
  pantalla.setTextColor(ST77XX_BLACK); 
  pantalla.setTextSize(3);             
  pantalla.setCursor(25, 35);          
  pantalla.print("Nivel");

  pantalla.setTextColor(ST77XX_BLACK);
  pantalla.setTextSize(3);
  pantalla.setCursor(58, 105);
  pantalla.print(nivel);
  pantalla.setCursor(38, 105);
  pantalla.print("<");
  pantalla.setCursor(78, 105);
  pantalla.print(">");

  // Dibujar la serpiente quieta en el menú
  pantalla.fillCircle(65, 75, 3, ST77XX_GREEN); 
  pantalla.fillRect(63, 78, 5, 3, ST77XX_GREEN); 
  pantalla.drawPixel(63, 74, ST77XX_BLACK); 
  pantalla.drawPixel(67, 74, ST77XX_BLACK); 
  pantalla.drawLine(65, 73, 65, 71, ST77XX_RED); 
}

void actualizarMenu() {
  pantalla.fillRect(58, 105, 18, 22, ST77XX_WHITE);
  pantalla.fillRect(50, 60, 30, 35, ST77XX_WHITE);

  pantalla.setTextColor(ST77XX_BLACK);
  pantalla.setTextSize(3);
  pantalla.setCursor(58, 105);
  pantalla.print(nivel);

  pantalla.fillCircle(65, 75, 3, ST77XX_GREEN);
  pantalla.fillRect(63, 78, 5, 3, ST77XX_GREEN);
  pantalla.drawPixel(63, 74, ST77XX_BLACK);
  pantalla.drawPixel(67, 74, ST77XX_BLACK);
  pantalla.drawLine(65, 73, 65, 71, ST77XX_RED);
}

void comenzarJuego() {
  pantalla.fillScreen(ST77XX_WHITE); 

  // Inicializar los segmentos iniciales en fila vertical hacia abajo
  for (int i = 0; i < largoActual; i++) {
    cuerpoX[i] = 65;
    cuerpoY[i] = 70 + (i * velocidad);
  }

  if (nivel == 2) {
    pantalla.fillRect(0, 0, 30, 30, ST77XX_BLACK);     
    pantalla.fillRect(103, 0, 25, 25, ST77XX_BLACK);   
    pantalla.fillRect(49, 120, 30, 40, ST77XX_BLACK);   
  }
  else if (nivel == 3) {
    pantalla.fillRect(38, 0, 52, 15, ST77XX_BLACK);    
    pantalla.fillRect(34, 130, 60, 30, ST77XX_BLACK);  
    pantalla.fillRect(0, 60, 23, 40, ST77XX_BLACK);   
  }

  for (int i = 0; i < cantidadmanzanas; i++) {
    generarManzanas(i);
  }

  dibujarManzanas();
  dibujarSerpiente();
}

// --- FUNCIONES DE MANZANAS ---
void generarManzanas(int i) {
  bool posicionValida = false;

  while (!posicionValida) {
    manzanaX[i] = random(8, 120);
    manzanaY[i] = random(18, 152);

    posicionValida = true;

    // 1. Evitar que aparezca encima de la cabeza o el cuerpo
    for (int k = 0; k < largoActual; k++) {
      if (abs(manzanaX[i] - cuerpoX[k]) < 10 &&
          abs(manzanaY[i] - cuerpoY[k]) < 10) {
        posicionValida = false;
      }
    }

    // 2. Evitar que aparezca encima de otra manzana
    for (int j = 0; j < cantidadmanzanas; j++) {
      if (j != i &&
          abs(manzanaX[i] - manzanaX[j]) < 12 &&
          abs(manzanaY[i] - manzanaY[j]) < 12) {
        posicionValida = false;
      }
    }

    // 3. Obstáculos del nivel 2
    if (nivel == 2) {
      if (manzanaX[i] < 36 && manzanaY[i] < 36) posicionValida = false;
      if (manzanaX[i] > 97 && manzanaY[i] < 31) posicionValida = false;
      if (manzanaX[i] > 43 && manzanaX[i] < 85 && manzanaY[i] > 114) posicionValida = false;
    }

    // 4. Obstáculos del nivel 3
    if (nivel == 3) {
      if (manzanaX[i] > 32 && manzanaX[i] < 96 && manzanaY[i] < 21) posicionValida = false;
if (manzanaX[i] > 28 && manzanaX[i] < 100 && manzanaY[i] > 124) posicionValida = false;
if (manzanaX[i] < 29 && manzanaY[i] > 54 && manzanaY[i] < 106) posicionValida = false;
}
}
}
void dibujarManzanas() {
for (int i = 0; i < cantidadmanzanas; i++) {
pantalla.fillCircle(manzanaX[i], manzanaY[i], 4, ST77XX_RED);
pantalla.fillCircle(manzanaX[i] - 2, manzanaY[i] - 2, 2, ST77XX_RED);
pantalla.drawLine(
manzanaX[i], manzanaY[i] - 4,
manzanaX[i] + 1, manzanaY[i] - 6,
ST77XX_GREEN
);
}
}
void comerManzana() {
for (int i = 0; i < cantidadmanzanas; i++) {
if (abs(cuerpoX[0] - manzanaX[i]) < 7 &&
abs(cuerpoY[0] - manzanaY[i]) < 7) {
// Se borra la manzana
pantalla.fillCircle(manzanaX[i], manzanaY[i], 6, ST77XX_WHITE);
// Si no llegó al límite máximo, agrega un segmento nuevo en la cola
if (largoActual < MAX_LARGO) {
cuerpoX[largoActual] = cuerpoX[largoActual - 1];
cuerpoY[largoActual] = cuerpoY[largoActual - 1];
largoActual++;
}
generarManzanas(i);
puntuacion += 50;
}
}
}
